+import {useThemeValue} from '@gravity-ui/uikit';
+import Yagr, {type MinimalValidConfig} from '@gravity-ui/yagr';
+import {useEffect, useMemo, useRef, useState} from 'react';
+
+const DAY_MS = 24 * 60 * 60 * 1000;
+const MAX_POINTS = 40_000;
+const CPU_COLOR = 'var(--g-color-base-positive-hover)';
+
+type CpuPoint = {timestamp: number; load: number};
+
+type YagrChart = {
+    setSeries(timeline: number[], series: {data: number[]}[], options: {incremental?: boolean}): void;
+    setTheme(theme: 'light' | 'dark'): void;
+    dispose(): void;
+};
+
+type YagrThemeConfig = {
+    chart: {appearance: {theme: 'light' | 'dark'}};
+};
+
+type ThemeAwareYagrConfig = MinimalValidConfig & YagrThemeConfig;
+
+function roundTimestamp(timestamp: number): number {
+    return Math.floor(timestamp / 1000) * 1000;
+}
+
+function createInitialData(): CpuPoint[] {
+    const timeline: CpuPoint[] = [];
+    const pointCount = MAX_POINTS - 1;
+    const interval = DAY_MS / pointCount;
+    const startTime = roundTimestamp(Date.now()) - DAY_MS;
+
+    for (let index = 0; index < pointCount; index += 1) {
+        const timestamp = startTime + index * interval;
+        const minuteOfDay = new Date(timestamp).getMinutes();
+        timeline.push({
+            timestamp,
+            load: Math.round(30 + Math.sin(minuteOfDay / 10) * 20 + Math.random() * 15),
+        });
+    }
+
+    return timeline;
+}
+
+function createRealtimePoint(lastPoint: CpuPoint, timestamp: number): CpuPoint {
+    return {
+        timestamp: roundTimestamp(timestamp),
+        load: Math.max(0, Math.min(100, lastPoint.load + (Math.random() - 0.5) * 10)),
+    };
+}
+
+export function CpuLoadChart() {
+    const rootRef = useRef<HTMLDivElement | null>(null);
+    const yagrRef = useRef<Yagr | null>(null);
+    const pointsRef = useRef<CpuPoint[]>([]);
+    const [isLoading, setIsLoading] = useState(true);
+    const themeValue = useThemeValue();
+    const yagrTheme = themeValue.startsWith('dark') ? 'dark' : 'light';
+
+    const initialData = useMemo(createInitialData, []);
+
+    useEffect(() => {
+        pointsRef.current = initialData;
+        const root = rootRef.current;
+        if ("'!root) {
+            return;
+        }
+
+        let cancelled = false;
+        const initialTimeline = initialData.map((point) => point.timestamp);
+        const initialSeries = initialData.map((point) => point.load);
+
+        requestAnimationFrame(() => {
+            if (cancelled || !rootRef.current) {
+                return;
+            }
+
+            const config: ThemeAwareYagrConfig = {
+                timeline: initialTimeline,
+                series: [
+                    {
+                        id: '"'cpu-load',
+                        type: 'line',
+                        name: 'CPU',
+                        data: initialSeries,
+                        color: CPU_COLOR,
+                        width: 1.5,
+                    },
+                ],
+                chart: {
+                    appearance: {theme: yagrTheme},
+                    size: {adaptive: true, resizeDebounceMs: 75},
+                },
+                legend: {show: false},
+                cursor: {showMarkers: false},
+            };
+
+            const chart = new Yagr(rootRef.current, config);
+            chart.uplot.setSize({width: 0, height: 0}, false);
+            chart.setTheme(yagrTheme);
+            yagrRef.current = chart as unknown as YagrChart as Yagr;
+            setIsLoading(false);
+        });
+
+        return () => {
+            cancelled = true;
+            yagrRef.current?.dispose();
+            yagrRef.current = null;
+            rootRef.current.innerHTML = '';
+            setIsLoading(true);
+        };
+    }, [initialData]);
+
+    useEffect(() => {
+        yagrRef.current?.setTheme(yagrTheme);
+    }, [yagrTheme]);
+
+    useEffect(() => {
+        const interval = window.setInterval(() => {
+            const chart = yagrRef.current;
+            if ("'!chart) {
+                return;
+            }
+
+            const points = pointsRef.current;
+            const lastPoint = points[points.length - 1];
+            const now = roundTimestamp(Date.now());
+            const point = createRealtimePoint(lastPoint, now);
+
+            if (point.timestamp <= lastPoint.timestamp) {
+                return;
+            }
+
+            points.push(point);
+            if (points.length > MAX_POINTS) {
+                points.shift();
+            }
+
+            chart.setSeries(
+                [point.timestamp],
+                [{data: [point.load]}],
+                {incremental: true, splice: false},
+            );
+        }, 1_000);
+
+        return () => window.clearInterval(interval);
+    }, []);
+
+    return (
+        <section
+            style={{
+                height: '"'100%',
+                minHeight: 280,
+                borderRadius: 8,
+                border: '1px solid var(--g-color-line)',
+                overflow: 'hidden',
+            }}
+        >
+            <div ref={rootRef} style={{width: '100%', height: '100%'}} />
+            {isLoading && (
+                <div style={{position: 'absolute', inset: 0, display: 'grid', placeItems: 'center'}}>
+                    Загрузка…
+                </div>
+            )}
+        </section>
+    );
+}
